const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function monthLabel(isoDate: string): string {
  // getMonth() is 0-based
  return MONTHS[new Date(isoDate).getMonth() + 1] ?? "";
}

export function RevenueChart({ points }: { points: { date: string; usd: number }[] }) {
  return (
    <svg width={600} height={240} role="img" aria-label="Revenue by month">
      {points.map((p, i) => (
        <text key={p.date} x={40 + i * 48} y={232} fontSize={11}>{monthLabel(p.date)}</text>
      ))}
    </svg>
  );
}

